  "Map tiles cleared": "تم مسح بيانات الخريطة المحفوظة",
  "Maps": "الخرائط",
  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "تُحفظ كل منطقة تتصفحها، فتعمل مجددًا دون إشارة. ويمكنك أيضًا تنزيل منطقة قبل السفر. يحتاج البحث عن الأماكن إلى اتصال؛ أما أماكنك المحفوظة فيمكن البحث فيها دونه.",
  "offline — showing saved tiles": "دون اتصال — تُعرض الخريطة المحفوظة",
  "Search a place — مدينة نصر، القاهرة": "ابحث عن مكان — مدينة نصر، القاهرة",
