  "File Converter": "محوّل الملفات",
  "Choose a file": "اختر ملفًا",
  "Translate…": "ترجمة…",
  "Translating into {l} — part {n} of {t}…": "جارٍ الترجمة إلى {l} — الجزء {n} من {t}…",
  "{n} piece(s) couldn't be translated and were left as they were.": "تعذّرت ترجمة {n} من الأجزاء وتُركت كما هي.",
  "Translated by the AI on your phone — check important names and numbers.": "ترجمها الذكاء الاصطناعي على هاتفك — راجع الأسماء والأرقام المهمة.",
  "Translating needs an AI model — open Engine and install one.": "تحتاج الترجمة إلى نموذج ذكاء اصطناعي — افتح المحرّك وثبّت واحدًا.",
  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "يترجمه الذكاء الاصطناعي على هاتفك جزءًا جزءًا؛ وتبقى العناوين والقوائم والجداول والأرقام في أماكنها. وتستغرق الملفات الطويلة بضع دقائق.",
  "Spanish": "الإسبانية",
  "Unlimited video downloads in the quality you choose": "تنزيل فيديوهات بلا حدود بالجودة التي تختارها",
  "Video Downloader": "منزّل الفيديو",
  "Paste a video link, pick the quality, save it to your phone": "الصق رابط الفيديو، واختر الجودة، واحفظه على هاتفك",
  "Copy a video's link, paste it here, pick the quality — it's saved to your phone's Movies folder. Works with direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons and pages that show a plain video.": "انسخ رابط الفيديو، والصقه هنا، واختر الجودة — يُحفظ في مجلد الأفلام بهاتفك. يعمل مع روابط الفيديو المباشرة وGoogle Drive وDropbox وarchive.org وWikimedia Commons والصفحات التي تعرض فيديو عاديًا.",
  "Find the video": "ابحث عن الفيديو",
  "Looking for the video…": "جارٍ البحث عن الفيديو…",
  "Choose the quality": "اختر الجودة",
  "Download": "نزّل",
  "Downloads": "التنزيلات",
  "Audio only": "الصوت فقط",
  "Video": "فيديو",
  "Original": "الأصل",
  "Play": "تشغيل",
  "Waiting for the internet…": "بانتظار الإنترنت…",
  "Only download videos you have the right to keep.": "نزّل فقط الفيديوهات التي يحق لك الاحتفاظ بها.",
  "The clipboard is empty — copy the video's link first": "الحافظة فارغة — انسخ رابط الفيديو أولًا",
  "Long-press the box and choose Paste": "اضغط مطولًا على الخانة واختر «لصق»",
  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "هذا ليس رابطًا. انسخ رابط الفيديو (يبدأ بـ https://) والصقه هنا.",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "لا يسمح {site} بتنزيل فيديوهاته، لذا لا يستطيع Attune حفظها (يزيل Google Play التطبيقات التي تفعل ذلك). الروابط التي تعمل: روابط الفيديو المباشرة وGoogle Drive وDropbox وarchive.org وWikimedia Commons والصفحات التي تعرض ملف فيديو عاديًا.",
  "a streaming service": "خدمة بث",
  "this site": "هذا الموقع",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "هذا رابط بث مباشر (.m3u8) — يُبث على أجزاء ولا يمكن حفظه كملف واحد.",
  "Downloading works in the Android app.": "يعمل التنزيل في تطبيق Android.",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "لم يُعطِ Google Drive الملف — تأكد من مشاركته لـ «أي شخص لديه الرابط».",
  "This page plays a {site} video, which can't be downloaded.": "تعرض هذه الصفحة فيديو من {site}، ولا يمكن تنزيله.",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "تبث هذه الصفحة الفيديو على أجزاء (HLS)، ولا يمكن حفظه كملف واحد.",
  "No downloadable video was found on that page.": "لم نجد فيديو قابلًا للتنزيل في تلك الصفحة.",
  "That link didn't give a video file (the site sent {t}).": "لم يُعد هذا الرابط ملف فيديو (أرسل الموقع {t}).",
  "No downloadable video was found there.": "لم نجد هناك فيديو قابلًا للتنزيل.",
  "Free includes 3 video downloads a day — Pro is unlimited": "تتيح الخطة المجانية 3 تنزيلات فيديو يوميًا — وPro بلا حدود",
  "Downloading — you can close Attune, it keeps going": "جارٍ التنزيل — يمكنك إغلاق Attune وسيستمر",
  "The file was moved or deleted": "نُقل الملف أو حُذف",
  "The download failed — the link may have expired. Find it again and retry.": "فشل التنزيل — ربما انتهت صلاحية الرابط. ابحث عنه مجددًا وأعد المحاولة.",
  "PDF, Word, PowerPoint, Excel, photos — 80+ conversions, and translation": "PDF وWord وPowerPoint وExcel والصور — أكثر من 80 تحويلًا، والترجمة",
  "PDF ↔ Word, PowerPoint → PDF, photos → PDF, scanned paper → editable Word, Excel ↔ CSV ↔ JSON, e-books, web pages, subtitles, merge and split PDFs — on your phone. Your files are never uploaded to a converter website.": "PDF ↔ Word، وPowerPoint → PDF، وصور → PDF، وورق ممسوح ضوئيًا → Word قابل للتعديل، وExcel ↔ CSV ↔ JSON، والكتب الإلكترونية، وصفحات الويب، والترجمات، ودمج ملفات PDF وتقسيمها — على هاتفك. لا تُرفع ملفاتك أبدًا إلى موقع تحويل.",
  "PDF · Word · PowerPoint · Excel · CSV · photos · e-books · web pages · subtitles — several photos → one PDF, several PDFs → merged": "PDF · Word · PowerPoint · Excel · CSV · صور · كتب إلكترونية · صفحات ويب · ترجمات — عدة صور → ملف PDF واحد، وعدة ملفات PDF → ملف مدموج",
  "That kind of file can't be converted here yet. Try PDF, Word, PowerPoint, Excel, CSV, photos, text, e-books, web pages or subtitles.": "لا يمكن تحويل هذا النوع من الملفات هنا بعد. جرّب PDF أو Word أو PowerPoint أو Excel أو CSV أو الصور أو النصوص أو الكتب الإلكترونية أو صفحات الويب أو الترجمات.",
  "Pick one file — or several photos (→ one PDF), or several PDFs (→ merged).": "اختر ملفًا واحدًا — أو عدة صور (← ملف PDF واحد)، أو عدة ملفات PDF (← ملف مدموج).",
