  "That file isn't a Word / Excel file (not a zip).": "هذا الملف ليس ملف Word / Excel (ليس ملف zip).",
  "That file isn't a Word document.": "هذا الملف ليس مستند Word.",
  "That file isn't an Excel workbook.": "هذا الملف ليس مصنّف Excel.",
  "Unlimited file conversions, including scanned paper → editable Word": "تحويل ملفات بلا حدود، ومنها الورق الممسوح ضوئيًا → Word قابل للتعديل",
  "Unlimited Chat X-Rays: who owes you, promises and unanswered questions in your WhatsApp chats": "فحص محادثات بلا حدود: من يدين لك، والوعود، والأسئلة التي بلا إجابة في محادثات WhatsApp",
  "Chat X-Ray": "فحص المحادثة",
  "Money, promises & questions in a WhatsApp chat": "المال والوعود والأسئلة في محادثة WhatsApp",
  "Who owes whom, what was promised, which dates were agreed and which questions got no answer — read from a WhatsApp chat on your phone. The chat never leaves the phone.": "من يدين لمن، وما الذي وُعد به، وما المواعيد المتفق عليها، وأي الأسئلة بقيت بلا إجابة — تُقرأ من محادثة WhatsApp على هاتفك. ولا تغادر المحادثة هاتفك أبدًا.",
  "In WhatsApp, open the chat → ⋮ → More → Export chat → Without media.": "في WhatsApp: افتح المحادثة ← ⋮ ← المزيد ← تصدير المحادثة ← بدون وسائط.",
  "Pick Attune in the share list — or save the file and choose it here.": "اختر Attune من قائمة المشاركة — أو احفظ الملف واخترْه هنا.",
  "Choose the exported chat (.txt)": "اختر المحادثة المُصدَّرة (‎.txt)",
  "…or paste the chat text here": "…أو الصق نص المحادثة هنا",
  "Read the pasted chat": "اقرأ المحادثة الملصقة",
  "Earlier X-rays": "فحوصات سابقة",
