  "No money owed or paid was found in this part of the chat.": "لم نجد مبالغ مستحقة أو مدفوعة في هذا الجزء من المحادثة.",
  "Totals are added up by the phone from the messages quoted — check them before asking anyone to pay.": "يجمع الهاتف الإجماليات من الرسائل المقتبسة — تحقق منها قبل أن تطلب من أحد الدفع.",
