  "Highest resolution — sharpen every picture ×4 (2048 px; about 1–3 minutes more without a graphics chip)": "أعلى دقة — حسّن وضوح كل صورة ×4 (2048 بكسل؛ تستغرق من دقيقة إلى 3 دقائق إضافية بلا شريحة رسومات)",
  "The picture is ready at {w} px; sharpening it failed: {e}": "الصورة جاهزة بعرض {w} بكسل؛ لكن تحسين الوضوح فشل: {e}",
