  "The AI on your phone rewords — it never adds a number, date or skill you didn't write. Anything it suggests is shown first.": "يعيد الذكاء الاصطناعي على هاتفك صياغة النص فقط — ولا يضيف أبدًا رقمًا أو تاريخًا أو مهارة لم تكتبها. وكل ما يقترحه يُعرض لك أولًا.",
