  "Your own recipes for the AI — create, import, share": "وصفاتك الخاصة للذكاء الاصطناعي — أنشئ، واستورد، وشارك",
  "Your own recipes for the AI: how to write your quotes, replies, lessons. Start a message with a skill's command, or let the app pick it when your question fits. A skill adds instructions, facts and a checklist to your question; a small program inside it (only if you keep one) runs offline in a locked box.": "وصفاتك الخاصة للذكاء الاصطناعي: كيف يكتب عروض أسعارك وردودك ودروسك. ابدأ رسالتك بأمر مهارة، أو دع التطبيق يختارها حين يناسبها سؤالك. تضيف المهارة تعليمات وحقائق وقائمة تحقق إلى سؤالك؛ أما البرنامج الصغير بداخلها (إن احتفظت بواحد) فيعمل دون إنترنت داخل صندوق مغلق.",
