  "Start a message with it to use this skill, e.g. “/quote 3 birthday cakes for Friday”.": "ابدأ به رسالتك لاستخدام هذه المهارة، مثل «/quote 3 كعكات عيد ميلاد ليوم الجمعة».",
  "When to use it": "متى تُستخدم",
