  "For power users. Community models are not tested by Attune: a model bigger than about 40% of this phone's memory will run slowly and hot, or be closed by Android. Check the size on its Hugging Face page first, and prefer the Q4 file.": "للمستخدمين المتقدمين. لا يختبر Attune نماذج المجتمع: النموذج الأكبر من نحو 40% من ذاكرة هذا الهاتف سيعمل ببطء وسخونة، أو سيغلقه Android. تحقق من حجمه في صفحته على Hugging Face أولًا، وفضّل ملف Q4.",
