  "Wikipedia · the question leaves the device, the answer is still written here": "ويكيبيديا · يغادر السؤال الجهاز، لكن الإجابة تُكتب هنا",
  "Runs on this device · no account · works with no signal": "يعمل على هذا الجهاز · بلا حساب · ويعمل دون إشارة",
