  "or drag a file or some text onto this box": "أو اسحب ملفًا أو نصًا إلى هذا المربع",
  "A photo is read word for word and the text kept, so a whiteboard, a receipt or a handwritten site note becomes searchable — and anything promised on it shows up on the right.": "تُقرأ الصورة كلمة كلمة ويُحفظ نصها، فتصبح السبورة أو الإيصال أو ملاحظة الموقع المكتوبة بخط اليد قابلة للبحث — وأي شيء وُعد به فيها يظهر على اليمين.",
  "Your words": "كلماتك",
  "The words your trade uses, that a general model gets wrong every time. Teach it once and it never gets them wrong again — in answers, documents and translations alike. This is the part of the app that gets better the longer you use it, and the part nobody can copy.": "الكلمات التي يستخدمها مجال عملك، والتي يخطئ فيها النموذج العام في كل مرة. علّمه إياها مرة واحدة فلا يخطئ فيها ثانية — في الإجابات والمستندات والترجمات على حد سواء. هذا هو الجزء الذي يتحسن في التطبيق كلما استخدمته أكثر، والجزء الذي لا يستطيع أحد نسخه.",
  "the word (سطحة, mobilisation…)": "الكلمة (سطحة، mobilisation…)",
  "how you want it written": "كيف تريد أن تُكتب",
  "Teach it": "علّمه",
  "Write the rule in the first box": "اكتب القاعدة في المربع الأول",
  "or save the first box as a writing rule — “always state VAT separately”": "أو احفظ المربع الأول كقاعدة كتابة — «اذكر ضريبة القيمة المضافة دائمًا بشكل منفصل»",
