  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "يعرف كيف تسير الأمور فعلًا هنا — الأسعار العادلة، والمبالغات الشائعة في الأسعار، وما يُعدّ وقاحة. وسيخبرك حين يحتاج الأمر إلى بيانات مباشرة لا يملكها دون اتصال.",
