  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "يحافظ على معناك وحقائقك تمامًا — ويغيّر فقط طريقة القراءة. عيّنة الكتابة اختيارية، لكنها تصنع أكبر فرق.",
  "Rewritten": "أُعيدت كتابته",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "الصق نصًا جامدًا أو يبدو مكتوبًا بالذكاء الاصطناعي، وأضف عيّنة من كتابتك، فيعود بأسلوبك — المعنى نفسه، وإيقاع بشري.",
