  "Optimize next prompt": "حسّن الأمر التالي",
  "Optimize my prompt": "حسّن أمري",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "الحلقة: اكتب ما تريد ← احصل على أمر محسَّن ← أرسله ← أعد الرد إلى هنا ← يصبح كل أمر تالٍ أدق. وفي تطبيق الهاتف تحلّ قائمة المشاركة محل النسخ واللصق تمامًا.",
  "· older turns compacted": "· ضُغطت الأدوار الأقدم",
