  "Use recipe": "استخدم الوصفة",
  "Recipes ship offline and refresh from your server when online — so they stay current as models change. Point": "تأتي الوصفات مع التطبيق وتعمل دون اتصال، وتتحدث من خادمك عند الاتصال — فتبقى حديثة مع تغير النماذج. وجّه",
