  "Only the question you look up and the pages opened leave the phone — never your conversation, files or memory.": "لا يغادر الهاتف سوى السؤال الذي تبحث عنه والصفحات المفتوحة — ولا تغادر محادثتك أو ملفاتك أو ذاكرتك أبدًا.",
