  "Add it to your ledger in Money? You'll pick the account and confirm there.": "أتريد إضافتها إلى دفترك في «المال»؟ ستختار الحساب وتؤكد هناك.",
  "Spotting": "تبقيع",
  "Light": "خفيفة",
  "Medium": "متوسطة",
  "Heavy": "غزيرة",
  "Same as text": "مثل النص",
  "A message": "رسالة",
  "Arabic → summary": "العربية ← ملخص",
  "A calculation": "عملية حسابية",
  "Period log": "سجل الدورة",
  "item": "عنصر",
  "items": "عناصر",
  "learned": "تعلّمها",
  "kept": "محفوظ",
  "15 questions a day": "15 سؤالًا يوميًا",
  "3 templates · 5 history items": "3 قوالب · 5 عناصر في السجل",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "معرفة نموذج 35B، و3B فقط تعمل على كل رمز — إجابات تقارب أقوى النماذج بسرعة يتحملها حاسوب محمول. نموذج «مزيج الخبراء» يُبقي كل الخبراء في الذاكرة رغم أن قلة منهم تعمل لكل رمز، لذا يحتاج ذاكرة نموذج 35B وحوسبة نموذج 3B.",
  "A bigger length budget for reports, plans and analysis.": "مساحة أطول للتقارير والخطط والتحليلات.",
  "Always think before answering": "فكّر دائمًا قبل الإجابة",
  "Ask it as much as you like — no daily limit": "اسأله كما تشاء — دون حد يومي",
  "Can run {m}": "يمكنه تشغيل {m}",
  "Detected about {n} GB of memory": "رُصدت ذاكرة بنحو {n} GB",
  "Your phone reports {n} GB of memory": "يُبلغ هاتفك عن ذاكرة {n} GB",
  "Your computer reports {n} GB of memory": "يُبلغ حاسوبك عن ذاكرة {n} GB",
  "which leaves plenty of room for long conversations": "وهذا يترك مساحة واسعة للمحادثات الطويلة",
  "which is comfortable for everyday use": "وهذا مريح للاستخدام اليومي",
  "which is enough, with shorter conversations": "وهذا يكفي، مع محادثات أقصر",
  ", ": "، ",
  "Documents, fleet records, copilot, every domain pack": "المستندات، سجلات الأسطول، المساعد، كل حزم المجالات",
  "Download it on Wi-Fi. After that it never uses your connection again.": "نزّله عبر Wi-Fi. بعد ذلك لن يستخدم اتصالك أبدًا.",
  "Small enough to download on mobile data if you need to.": "صغير بما يكفي لتنزيله عبر بيانات الجوال عند الحاجة.",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "هذا نموذج كبير بالنسبة إلى هاتف. سيعمل، لكنه سيبطؤ بوضوح عندما يسخن الهاتف — أبقِ الإجابات قصيرة، أو اختر النموذج الأصغر.",
  "Download {m} · {s} GB": "نزّل {m} · {s} GB",
  "Every tool, and all 31 country packs": "كل الأدوات، وكل حزم الدول الـ31",
  "Finds what you promised people, from your own words": "يجد ما وعدت به الناس، من كلامك أنت",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "عشوائية ثابتة، فيعطي سير العمل النتيجة نفسها في كل مرة يعمل فيها.",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "بحث مجاني في الويب: يسأل DuckDuckGo وBing وMojeek معًا، ثم يقرأ أهم الصفحات كاملة، فتأتي الإجابات من نصوص حقيقية.",
  "Free · no key": "مجاني · دون مفتاح",
  "Install · {s}": "ثبّت · {s}",
  "Installing… {p}%": "جارٍ التثبيت… {p}%",
  "It remembers everything and can search it": "يتذكر كل شيء ويمكنه البحث فيه",
  "Learns your vocabulary and writes the way you do": "يتعلّم مفرداتك ويكتب بأسلوبك",
  "Long answers": "إجابات طويلة",
  "No account, no sign-in, nothing uploaded": "دون حساب، دون تسجيل دخول، ولا يُرفع شيء",
  "Not running": "متوقف",
  "Running": "يعمل",
  "Loading the model…": "جارٍ تحميل النموذج…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "لا يمكن لأي شيء في التطبيق الوصول إلى الإنترنت — لا بحث في الويب ولا خرائط ولا تنزيلات. يظل النموذج وكل ما على الهاتف يعمل.",
  "Offline lock": "قفل الاتصال",
  "Same question, same answer": "السؤال نفسه، الإجابة نفسها",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "يفكّر النموذج أولًا في كل سؤال. أفضل بوضوح في المسائل الصعبة، لكن على الهاتف تبدأ الإجابة بعد 30–90 ثانية. عند الإيقاف: اضغط «فكّر» على الأسئلة التي تحتاجه فقط.",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "النموذج نفسه أدناه، مع ذاكرة تتسع لكتاب كامل من السياق دفعة واحدة. على جهاز بذاكرة 48 GB، يُستحسن إنفاق الذاكرة الزائدة على السياق لا على الدقة — يمكنك أن تعطيه عقدًا كاملًا أو ملاحظات عام كامل فيبقيها كلها في نظره.",
  "The whole assistant, on your device": "المساعد بأكمله على جهازك",
  "Works entirely offline. No account, ever.": "يعمل دون اتصال تمامًا. ودون حساب أبدًا.",
