  "This opens the phone's own app — it works in the Android app.": "يفتح هذا تطبيق الهاتف نفسه — ويعمل في تطبيق Android.",
  "Clock opened with the alarm filled in · {when} — tap Save there.": "فُتحت الساعة والمنبّه جاهز · {when} — اضغط «حفظ» هناك.",
