  "Calendar opened with the event filled in · {when} — tap Save there.": "فُتح التقويم والموعد جاهز · {when} — اضغط «حفظ» هناك.",
  "WhatsApp opened with the message ready — tap Send there.": "فُتح WhatsApp والرسالة جاهزة — اضغط «إرسال» هناك.",
