  "Pick a time in the future": "اختر وقتًا في المستقبل",
  "Reminders & actions": "التذكيرات والإجراءات",
  "Just say it in Chat: “remind me tomorrow at 9 to call Ahmed”, “صحيني الساعة 6”, “ابعت لمحمود على الواتساب إني هتأخر”. You always confirm first.": "قلها في المحادثة فحسب: «ذكّرني غدًا الساعة 9 بالاتصال بأحمد»، «صحيني الساعة 6»، «ابعت لمحمود على الواتساب إني هتأخر». وأنت تؤكد دائمًا أولًا.",
  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "الإشعارات معطّلة لـ Attune — اضغط للسماح بها، وإلا فلن تظهر التذكيرات.",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "قد تتأخر التذكيرات حتى 10 دقائق. اضغط للسماح بـ«المنبّهات والتذكيرات» لـ Attune لترنّ في موعدها تمامًا.",
  "In the browser reminders are only listed — the Android app rings them.": "في المتصفح تُعرض التذكيرات فقط — أما الرنين فيعمل في تطبيق Android.",
  "Add one": "أضف تذكيرًا",
  "What to remind you about": "بماذا أذكّرك؟",
  "Add reminder": "أضف تذكيرًا",
  "Coming up": "القادم",
  "Nothing set.": "لم يُضبط شيء.",
