  "Only the first parts of this long document were summarised.": "لُخّصت الأجزاء الأولى فقط من هذا المستند الطويل.",
  "Open a PDF, Word file, book or web page. Read it here and chat with it — every answer shows the page it came from. Everything stays on your phone.": "افتح ملف PDF أو Word أو كتابًا أو صفحة ويب. اقرأه هنا وحاوره — كل إجابة تُظهر الصفحة التي جاءت منها. كل شيء يبقى على هاتفك.",
  "Open a file": "افتح ملفًا",
