  "Page {n}": "الصفحة {n}",
  "Pick a PDF, Word, PowerPoint, e-book, web page or text file.": "اختر ملف PDF أو Word أو PowerPoint أو كتابًا إلكترونيًا أو صفحة ويب أو ملفًا نصيًا.",
  "Pick the file again to continue — files are not copied into the app.": "اختر الملف مجددًا للمتابعة — لا تُنسخ الملفات إلى التطبيق.",
  "Read pages": "اقرأ الصفحات",
  "Reading and searching work now. To chat with the file, install a model in Engine.": "القراءة والبحث يعملان الآن. لمحاورة الملف، ثبّت نموذجًا من المحرّك.",
  "Reading pages {p}…": "جارٍ قراءة الصفحات {p}…",
