  "This answer could not be tied to a page — check the pages listed below before relying on it.": "تعذّر ربط هذه الإجابة بصفحة — راجع الصفحات المذكورة أدناه قبل الاعتماد عليها.",
  "Writing the answer…": "جارٍ كتابة الإجابة…",
