  "Checklist: what every answer must satisfy (one per line, optional)": "قائمة تحقق: ما يجب أن تستوفيه كل إجابة (واحد في كل سطر، اختياري)",
  "Facts the AI should know (prices, rules, terms — optional)": "حقائق يجب أن يعرفها الذكاء الاصطناعي (أسعار، قواعد، شروط — اختياري)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "افصل بين الموضوعات بسطر فارغ. تُستخدم فقط الفقرات المناسبة للسؤال، لذا يمكن أن يكون طويلًا.",
  "Facts": "الحقائق",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "ويشغّل أيضًا هذا البرنامج الصغير على هاتفك (دون إنترنت، في صندوق مقفل — بلا إنترنت ولا ملفات ولا وصول إلى التطبيق)",
  "Edit or improve my CV": "عدّل سيرتي الذاتية أو حسّنها",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "اذكر ما تريد إضافته أو تغييره («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022»، «change my phone to …»)، أو اتركه فارغًا لتجعلها أكثر احترافية فقط. سترى النتيجة قبل حفظها.",
  "What should be added or changed? (optional)": "ما الذي يجب إضافته أو تغييره؟ (اختياري)",
