  "The model answered without any code — try asking again in other words.": "أجاب النموذج دون أي كود — حاول السؤال مجددًا بكلمات أخرى.",
  "A picture — Studio draws it on this phone": "صورة — يرسمها Studio على هذا الهاتف",
