  "Create": "إنشاء",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "جودة صور حديثة في 4 خطوات: أشخاص وأماكن ومنتجات ونصوص داخل الصور. ويعدّل أيضًا صورة تعطيه إياها («اجعلها ليلًا»، «أزل السيارة»).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "صِف الصورة بالعربية أو الإنجليزية — مثل «فلوكة على النيل عند الغروب»",
  "Developing the picture…": "جارٍ إظهار الصورة…",
