  "Studio works in the Android app.": "يعمل Studio في تطبيق Android.",
  "The chat model was paused to make room, and is loading again.": "أُوقف نموذج المحادثة مؤقتًا لإفساح المجال، ويُعاد تحميله الآن.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "لا يحتوي هذا الـAPK على محرّك صور بعد — يأتي مع الـAPK التالي المبني على GitHub.",
  "This build draws on the CPU.": "هذا الإصدار يرسم على CPU.",
  "This build of the app has no picture engine yet.": "لا يحتوي هذا الإصدار من التطبيق على محرّك صور بعد.",
  "This phone has {n} GB — it may be too little for pictures.": "في هذا الهاتف {n} GB — قد لا تكفي للصور.",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "لا يحتوي هذا الإصدار من Attune على محرّك صور يعمل على شريحة الرسوميات، لذا تُرسم الصور على CPU (أبطأ). تحديث قادم يضيفه.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "توقف محرّك الصور عن الاستجابة أثناء تحميل النموذج، فأُوقف. يعرض المحرّك ← سجل المحرّك آخر أسطره — أرسلها إلى الدعم.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "لم يستجب برنامج تشغيل GPU في هذا الهاتف، لذا تُرسم الصور على CPU (أبطأ).",
  "What should change? e.g. “make it night, with the street lights on”": "ما الذي يجب أن يتغير؟ مثل «اجعلها ليلًا، مع إضاءة أعمدة الشارع»",
