  "I couldn't make every test pass yet — here is the closest version; tap “Test & fix in Code” to keep going.": "لم أتمكن من إنجاح كل الاختبارات بعد — هذه أقرب نسخة؛ اضغط «اختبر وأصلح في الكود» للمتابعة.",
  "Working it out as a program…": "جارٍ الحل كبرنامج…",
