  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "أفضل صور يمكن لهذا الهاتف صنعها: إصدار 8-bit من FLUX.2 klein — تفاصيل أدق، ووجوه وأيدٍ ونصوص أنظف. ويعدّل صورك أيضًا بالتعليمات.",
  "Spreadsheet or document": "جدول بيانات أو مستند",
  "That file is too large (15 MB at most)": "هذا الملف كبير جدًا (15 MB كحد أقصى)",
  "What's in this file? Summarise what matters.": "ما الذي في هذا الملف؟ لخّص المهم.",
  "Checked — the reviewer fixed a mistake": "تم التحقق — صحّح المراجع خطأً",
