  "{v} of {n} tries agreed · checked": "اتفقت {v} من {n} محاولات · تم التحقق",
  "Computed from {f} on this phone": "محسوب من {f} على هذا الهاتف",
  "Used {n} of your corrections": "استُخدم {n} من تصحيحاتك",
  "Wrong? Teach the right answer": "خطأ؟ علّمه الإجابة الصحيحة",
  "What should it have said? Chat will answer this way next time you ask something like it.": "ماذا كان يجب أن يقول؟ ستجيب المحادثة بهذه الطريقة في المرة القادمة التي تسأل فيها شيئًا مشابهًا.",
  "The right answer": "الإجابة الصحيحة",
  "Why (optional) — e.g. “the marble falls out when the glass is turned over”": "السبب (اختياري) — مثل «تسقط الكرة الزجاجية عندما يُقلب الكوب»",
