  "e.g. unpaid invoices over 50,000 · jobs this month by customer · top 5 cranes by revenue": "مثلًا: الفواتير غير المدفوعة فوق 50,000 · أعمال هذا الشهر حسب العميل · أعلى 5 رافعات إيرادًا",
  "Load a model to ask your data in words.": "حمّل نموذجًا لتسأل بياناتك بالكلمات.",
