  "Describe a form — the fields to fill, in order": "صف النموذج — الحقول المطلوب تعبئتها بالترتيب",
  "e.g. a quick job form for the site: customer, crane, start date, days — status New": "مثلًا: نموذج سريع لعمل في الموقع: العميل، الرافعة، تاريخ البدء، الأيام — الحالة «جديد»",
  "Make the form": "أنشئ النموذج",
  "Load a model to make forms in words.": "حمّل نموذج ذكاء اصطناعي لإنشاء النماذج بالكلمات.",
