  "Save form": "احفظ النموذج",
  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "لا توجد نماذج بعد. يعرض النموذج الحقول التي تحتاجها فقط، بترتيبك، مع قيم جاهزة — اختره عند إضافة سجل.",
