  "Change the design in words — add fields to any table, new tables, links…": "غيّر التصميم بالكلمات — أضف حقولًا إلى أي جدول، أو جداول جديدة، أو روابط…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "مثلًا: أضف البريد الإلكتروني والرقم الضريبي إلى الموردين، وحقل أشهر الضمان إلى قطع الغيار",
  "Saved — send this file; it opens in any browser, no Attune needed": "تم الحفظ — أرسل هذا الملف؛ فهو يفتح في أي متصفح دون الحاجة إلى Attune",
  "Excel files need Python, which isn't in this build — use CSV.": "ملفات Excel تحتاج إلى Python، وهو غير موجود في هذا الإصدار — استخدم CSV.",
  "Making the Excel file…": "جارٍ إنشاء ملف Excel…",
  "Couldn't make the Excel file: {e}": "تعذّر إنشاء ملف Excel: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "قدّمه لفريقك كتطبيق: ملف واحد فيه كل البيانات — يفتح في متصفح أي هاتف أو حاسوب دون الحاجة إلى Attune. وعندما يلزم تغيير شيء، افتح الملف هنا (الأعمال ← فتح ملف تطبيق)، واطلب من الذكاء الاصطناعي، ثم أرسل التطبيق الجديد.",
  "Export as an app": "تصدير كتطبيق",
  "Excel workbook (all tables)": "مصنف Excel (كل الجداول)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "توقف محرّك الصور قبل اكتمال الصورة — ربما أغلقه Android لتحرير الذاكرة. جرّب «مسودة سريعة»، أو أغلق التطبيقات الأخرى وحاول مرة أخرى.",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "تعذّر إنشاء الصورة. افتح المحرّك ← سجل المحرّك وأرسل لي ما يظهر فيه.",
  "Multi-token prediction (faster writing)": "التنبؤ بعدة كلمات (كتابة أسرع)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "متوقف افتراضيًا: في بعض الهواتف يكرر الكلمات والأرقام («ItIt is is»، «20205»). فعّله فقط إذا بقيت الإجابات صحيحة.",
  "The last picture didn't finish:": "لم تكتمل الصورة الأخيرة:",
