  "Explicit action verbs beat vague asks (Anthropic 2026)": "أفعال الأمر الصريحة أفضل من الطلبات المبهمة (Anthropic 2026)",
  "State the desired outcome, not steps (OpenAI 2026)": "حدّد النتيجة المرجوّة لا الخطوات (OpenAI 2026)",
  "Concise prompts cut cost ~76% and lift quality": "الأوامر الموجزة تخفض التكلفة بنحو 76% وترفع الجودة",
  "Style examples outperform adjectives like 'professional'": "أمثلة الأسلوب أفضل من صفات مثل «احترافي»",
  "Scoping the edit prevents unwanted rewrites": "تحديد نطاق التعديل يمنع إعادة الكتابة غير المرغوبة",
  "Naming the goal and constraint shapes register": "ذكر الهدف والقيد يحدد مستوى اللغة",
