  "Data first, question last improves grounding": "البيانات أولًا والسؤال أخيرًا يحسّن الاستناد إلى المصدر",
  "Role-free outcome framing (2026 guidance)": "صياغة النتيجة دون دور محدد (إرشادات 2026)",
