  "Explicit critique requests beat 'what do you think'": "طلب النقد الصريح أفضل من «ما رأيك؟»",
  "Naming review axes prevents shallow feedback": "تسمية محاور المراجعة تمنع الملاحظات السطحية",
  "Include context + attempted fixes for accuracy": "أضف السياق ومحاولات الإصلاح السابقة لدقة أكبر",
  "Section-by-section output beats 'write a page'": "المخرجات قسمًا بقسم أفضل من «اكتب صفحة»",
  "Persona-specific prompts improve targeting": "الأوامر الموجهة لجمهور محدد تحسّن الاستهداف",
  "Stating criteria prevents generic pro/con lists": "ذكر المعايير يمنع قوائم الإيجابيات والسلبيات العامة",
  "Level-setting improves explanation fit": "تحديد المستوى يجعل الشرح أنسب",
  "Specifying length prevents rambling summaries": "تحديد الطول يمنع الملخصات المسهبة",
  "Ask to implement, not 'suggest changes' (Anthropic)": "اطلب التنفيذ، لا «اقترح تغييرات» (Anthropic)",
  "Reasoning models excel with clear scope, no examples": "نماذج التفكير تتفوق مع نطاق واضح ودون أمثلة",
  "Name every state so nothing is left ambiguous": "سمِّ كل حالة حتى لا يبقى شيء غامضًا",
  "Natural language + explicit variety works on GPT": "اللغة الطبيعية مع تنوع صريح تنجح مع GPT",
  "Outcome framing beats feature lists": "صياغة النتيجة أفضل من قوائم الميزات",
  "Gemini prefers direct, constrained prompts": "Gemini يفضّل الأوامر المباشرة المقيّدة",
  "Short + specific tone yields natural output": "النبرة القصيرة والمحددة تنتج مخرجات طبيعية",
  "Chain-of-thought: +~40% avg on hard reasoning (Wei et al.); MultiArith 18%→79%. Skip on reasoning models — minimal gain, more latency.": "سلسلة التفكير: نحو +40% في المتوسط على الاستدلال الصعب (Wei et al.)؛ MultiArith من 18% إلى 79%. تجاوزها مع نماذج التفكير — مكسب ضئيل وتأخير أكبر.",
  "1–5 examples (few-shot) raise pattern-task accuracy up to +43%; best on non-reasoning models like Gemini. Don't add examples for pure reasoning tasks — can hurt.": "من 1 إلى 5 أمثلة (few-shot) ترفع دقة مهام الأنماط حتى +43%؛ والأفضل مع النماذج غير المفكرة مثل Gemini. لا تضف أمثلة لمهام التفكير البحت — فقد تضر.",
  "OpenAI/Anthropic 2026: describe what a good result looks like; over-instructing adds noise on modern models.": "OpenAI/Anthropic 2026: صِف شكل النتيجة الجيدة؛ فالإفراط في التعليمات يضيف تشويشًا مع النماذج الحديثة.",
  "2026 practice: set how hard to think (thinking/effort control) and spend words on the outcome, not on 'think step by step'.": "ممارسة 2026: حدّد مقدار التفكير (التحكم في التفكير/الجهد) وأنفق الكلمات على النتيجة، لا على «فكّر خطوة بخطوة».",
  "Clarification-first reduces wasted turns — the model gathers missing context instead of guessing.": "البدء بالاستيضاح يقلل الجولات الضائعة — يجمع النموذج السياق الناقص بدل التخمين.",
  "Outcome criteria (what 'good' means) outperform process instructions on 2026 models.": "معايير النتيجة (ما معنى «جيد») تتفوق على تعليمات العملية مع نماذج 2026.",
  "Verification steps reduce errors on factual/analytical tasks.": "خطوات التحقق تقلل الأخطاء في المهام الواقعية والتحليلية.",
  "Specific details produce specific writing": "التفاصيل المحددة تنتج كتابة محددة",
  "Structure-to-prose is a well-suited LLM task": "تحويل البنية إلى نص مهمة تناسب النماذج اللغوية",
  "Explicit sections prevent rambling updates": "الأقسام الصريحة تمنع التحديثات المسهبة",
  "Asking for risks surfaces what you forgot": "طلب المخاطر يكشف ما نسيته",
  "Outcome framing keeps feedback constructive": "صياغة النتيجة تبقي الملاحظات بنّاءة",
  "Explicit audience prevents vague procedures": "تحديد الجمهور صراحةً يمنع الإجراءات المبهمة",
  "Spaced repetition beats massed practice": "التكرار المتباعد أفضل من التدريب المكثف",
  "Worked examples aid transfer to new problems": "الأمثلة المحلولة تساعد على نقل المعرفة إلى مسائل جديدة",
  "Planning prompts reduce rework on complex tasks": "أوامر التخطيط تقلل إعادة العمل في المهام المعقدة",
  "Explicitly requesting edge cases improves coverage": "طلب الحالات الحدّية صراحةً يحسّن التغطية",
  "Specificity outperforms enthusiasm in cold outreach": "التحديد أفضل من الحماس في التواصل الأول مع الغرباء",
  "Goal-anchored planning beats idea dumps": "التخطيط المرتبط بالهدف أفضل من سرد الأفكار",
  "Requesting alternatives counters fixation": "طلب البدائل يكسر التعلق بفكرة واحدة",
  "Citation requirements reduce unsupported claims": "اشتراط الاستشهاد يقلل الادعاءات غير المدعومة",
  "Grounding in supplied sources reduces hallucination; tell it to admit gaps.": "الاستناد إلى المصادر المقدمة يقلل الهلوسة؛ واطلب منه الاعتراف بالثغرات.",
  "Compress to {p}%": "اضغط إلى {p}%",
