  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "توقف تعريف GPU مرتين أثناء تحميل نموذج الصور، لذا حوّل Attune برنامج Studio إلى المعالج (يمكنك تجربة GPU مجددًا أدناه).",
