  "Highest resolution — sharpen every picture (×4 with the graphics chip; an instant ×2 without it)": "أعلى دقة — وضّح كل صورة (×4 مع شريحة الرسوميات؛ و×2 فوري دونها)",
  "The page was cut off — writing the rest…": "انقطعت الصفحة — جارٍ كتابة الباقي…",
