  "not read: {f}": "لم يُقرأ: {f}",
  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "من تطبيق Notebook في الهاتف: افتح ملاحظة (أو حدد عدة ملاحظات) ← مشاركة ← Attune ← «احفظ في الرف». أو اختر ملفات مُصدّرة هنا: نص، Word، PDF، صفحات ويب، Google Keep، Evernote، ملف ‎.zip، أو صور ملاحظات.",
  "Versions & prices": "الإصدارات والأسعار",
  "Pros & cons": "المزايا والعيوب",
  "Compare with rivals": "قارن بالمنافسين",
  "Latest news": "آخر الأخبار",
  "Those results were off-topic — searching another way…": "كانت تلك النتائج خارج الموضوع — جارٍ البحث بطريقة أخرى…",
  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "لم يُعثر على شيء — جرّب إضافة اسم المنطقة (مثلًا «… القاهرة الجديدة»)، أو حرّك الخريطة إلى هناك وابحث مجددًا.",
  "from the map's centre": "من مركز الخريطة",
  "saved place": "مكان محفوظ",
  "Save this place": "احفظ هذا المكان",
  "My location": "موقعي",
  "This phone can't share its location with the app.": "لا يستطيع هذا الهاتف مشاركة موقعه مع التطبيق.",
  "Location is off for Attune — allow it in the phone's settings to see where you are.": "الموقع متوقف لـ Attune — اسمح به في إعدادات الهاتف لترى مكانك.",
  "Couldn't get your location — check that location is on.": "تعذّر تحديد موقعك — تأكد من تشغيل الموقع.",
  "“{n}” isn't kept on this phone any more — pick the file again.": "«{n}» لم يعد محفوظًا على هذا الهاتف — اختر الملف مرة أخرى.",
  "tap to continue": "انقر للمتابعة",
  "The text and your questions are kept on this phone only. Forget removes them.": "النص وأسئلتك محفوظة على هذا الهاتف فقط. «انسَ» يحذفها.",
  "Web · Auto": "الويب · تلقائي",
  "Web: Auto — it searches only when a question needs fresh facts": "الويب: تلقائي — يبحث فقط عندما يحتاج السؤال إلى معلومات حديثة",
  "Pick the best model for each question": "اختر أفضل نموذج لكل سؤال",
  "Reading your {f} conversation…": "جارٍ قراءة محادثتك مع {f}…",
  "Reading the conversation…": "جارٍ قراءة المحادثة…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "الروابط المشتركة تُفتح في تطبيق Android — أو الصق نص المحادثة هنا.",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "قرأت محادثتك مع {f}{t} (نحو {n} كلمة). اسألني أي شيء عنها — راجعها، أو لخّصها، أو أكمل من حيث توقفت.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · الذكاء الاصطناعي يعمل على جهازك · لا حساب ولا تسجيل دخول · البحث في الويب فقط عندما يحتاجه السؤال (تلقائي) — أوقفه بزر الويب",
  "Web: Off — nothing is looked up": "الويب: متوقف — لا يُبحث عن شيء",
  "Search the web by itself when a question needs it": "ابحث في الويب تلقائيًا عندما يحتاج السؤال إلى ذلك",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "عندما يكون الويب متوقفًا في المحادثة، يظل البحث جاريًا في أسئلة الأسعار والمواصفات والأخبار والنتائج وهذا العام (كلمات البحث وحدها تغادر الهاتف). متوقف: لا يُبحث عن شيء إلا إذا شغّلت الويب.",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch Auto off in Engine": "Attune · الذكاء الاصطناعي يعمل على جهازك · لا حساب ولا تسجيل دخول · البحث في الويب فقط عندما يحتاجه السؤال (تلقائي) — أوقف الوضع التلقائي من المحرّك",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "كتب النموذج كلامًا بلا معنى — جارٍ إعادة تشغيله في الوضع الآمن وإعادة السؤال…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "يكتب هذا النموذج كلامًا بلا معنى على هذا الهاتف، حتى في الوضع الآمن. اختر نموذجًا آخر من المحرّك (Core يعمل جيدًا) وأخبرنا أيّها فشل.",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "الوضع الآمن مفعّل لهذا النموذج: كتب مرة كلامًا بلا معنى على هذا الهاتف، لذا يعمل دون حيل التسريع وبذاكرة كاملة الدقة (أبطأ قليلًا، والإجابات نفسها).",
  "Turn safe mode off": "أوقف الوضع الآمن",
  "Ready courses": "دورات جاهزة",
  "Or any topic you like": "أو أي موضوع تحبه",
  "When is my next period?": "متى دورتي التالية؟",
