  "I can answer about your next period, being late, ovulation, the fertile window, cycle and period length, your history and symptoms.": "أستطيع الإجابة عن دورتك التالية، والتأخر، والتبويض، وفترة الخصوبة، وطول الدورة ومدة الحيض، وسجلك والأعراض.",
