  "When you ask for a fact, Chat first looks it up in your sources and shows which one it used.": "عندما تسأل عن معلومة، تبحث المحادثة أولًا في مصادرك وتعرض المصدر الذي استخدمته.",
  "{mb} — {c} passages from {s} sources": "{mb} — {c} مقاطع من {s} مصادر",
  "What you get: small models answer facts from your sources correctly (in our test, 31 → 99 of 104 for the smallest model). Looking up takes under a tenth of a second and nothing leaves the phone.": "ما الذي تحصل عليه: النماذج الصغيرة تجيب عن الحقائق من مصادرك بدقة (في اختبارنا، من 31 إلى 99 من 104 لأصغر نموذج). يستغرق البحث أقل من عُشر ثانية ولا شيء يغادر الهاتف.",
