  "Search a place and tap “Save this place” — saved places work with no signal.": "ابحث عن مكان وانقر «احفظ هذا المكان» — الأماكن المحفوظة تعمل دون إشارة.",
  "Download a whole country once: every road, building, place and shop, and search — all with no signal. A new version is built every week from OpenStreetMap; the app tells you when one is ready.": "نزّل دولة كاملة مرة واحدة: كل طريق ومبنى ومكان ومتجر، مع البحث — وكل ذلك دون إشارة. تُبنى نسخة جديدة كل أسبوع من OpenStreetMap، ويخبرك التطبيق عندما تجهز.",
