  "Less than 6 months left after you return — many countries and airlines refuse this. Renew it or check this country's rule.": "متبقٍ أقل من 6 أشهر بعد عودتك — ترفض العديد من الدول وشركات الطيران ذلك. جدده أو تحقق من قواعد هذا البلد.",
