  "Back {d}": "العودة {d}",
  "Processing times differ — check the official portal": "تختلف أوقات المعالجة — راجع البوابة الرسمية",
  "e-Visa is open to all Egyptian passport holders. Visa on arrival if you hold a valid Schengen, UK or US visa.": "التأشيرة الإلكترونية متاحة لجميع حاملي جوازات السفر المصرية. تأشيرة عند الوصول إذا كنت تحمل تأشيرة شنغن أو المملكة المتحدة أو الولايات المتحدة سارية.",
  "GCC citizens enter freely with a national ID.": "يدخل مواطنو دول مجلس التعاون الخليجي بحرية باستخدام بطاقة الهوية الوطنية.",
  "e-Visa online, usually approved within minutes.": "تأشيرة إلكترونية عبر الإنترنت، وتتم الموافقة عليها عادة خلال دقائق.",
  "e-Visa online.": "تأشيرة إلكترونية عبر الإنترنت.",
  "Check the Saudi e-Visa portal — eligibility is by nationality.": "راجع بوابة التأشيرة الإلكترونية السعودية — الأهلية تعتمد على الجنسية.",
  "Visa required in advance. Usually arranged through the airline, a hotel or a sponsor.": "تأشيرة مطلوبة مسبقًا. يتم ترتيبها عادة عبر شركة الطيران أو فندق أو كفيل.",
  "GCC citizens enter with a national ID.": "يدخل مواطنو دول مجلس التعاون الخليجي بالهوية الوطنية.",
  "Visa-free on arrival for most EU nationals.": "دون تأشيرة عند الوصول لمعظم مواطني الاتحاد الأوروبي.",
  "Visa-free on arrival, extendable.": "دون تأشيرة عند الوصول، قابلة للتمديد.",
  "Most nationalities need a visa arranged before travel.": "تحتاج معظم الجنسيات إلى تأشيرة يتم ترتيبها قبل السفر.",
  "Hayya / e-Visa online before travel.": "بطاقة هيّا / تأشيرة إلكترونية عبر الإنترنت قبل السفر.",
  "Visa waiver on arrival, 90 days in 180.": "إعفاء من التأشيرة عند الوصول، 90 يومًا خلال 180 يومًا.",
  "Visa waiver on arrival.": "إعفاء من التأشيرة عند الوصول.",
  "Apply through the Hayya portal.": "التقديم عبر بوابة هيّا.",
  "Visa required in advance.": "التأشيرة مطلوبة مسبقًا.",
  "e-Visa online for most EU nationals.": "تأشيرة إلكترونية عبر الإنترنت لمعظم مواطني الاتحاد الأوروبي.",
  "Visa required for most nationalities.": "التأشيرة مطلوبة لمعظم الجنسيات.",
  "Visa required. The e-Visa route needs a valid US, Canadian, Australian, UK, Schengen or Japanese visa.": "التأشيرة مطلوبة. يتطلب مسار التأشيرة الإلكترونية تأشيرة سارية للولايات المتحدة أو كندا أو أستراليا أو بريطانيا أو شنغن أو اليابان.",
  "e-Visa online, cheap and quick.": "تأشيرة إلكترونية عبر الإنترنت، رخيصة وسريعة.",
  "Check the Royal Oman Police e-Visa portal.": "راجع بوابة التأشيرة الإلكترونية لشرطة عُمان السلطانية.",
  "e-Visa or visa on arrival, 14 days.": "تأشيرة إلكترونية أو تأشيرة عند الوصول، لمدة 14 يومًا.",
  "Visa on arrival or e-Visa.": "تأشيرة عند الوصول أو تأشيرة إلكترونية.",
  "e-Visa online for many nationalities.": "تأشيرة إلكترونية عبر الإنترنت للعديد من الجنسيات.",
  "No visa needed — one month.": "لا حاجة لتأشيرة — شهر واحد.",
  "Visa-free, 90 days.": "دون تأشيرة، لمدة 90 يومًا.",
  "Visa on arrival, or free with the Jordan Pass.": "تأشيرة عند الوصول، أو مجانًا مع التذكرة الموحدة (Jordan Pass).",
  "Visa on arrival for most; the Jordan Pass is usually the cheapest route.": "تأشيرة عند الوصول للأغلبية؛ التذكرة الموحدة (Jordan Pass) هي الخيار الأوفر عادة.",
