  "Explaining…": "جارٍ الشرح…",
  "Read it to me": "اقرأها لي",
  "Point the camera at any paper — a bill, a letter, a medicine box, a sign. I'll read it to you and tell you what to do.": "وجّه الكاميرا نحو أي مستند — فاتورة، خطاب، علبة دواء، لافتة. سأقرؤه لك وأخبرك بما يجب فعله.",
  "Take a photo": "التقط صورة",
  "From the gallery": "من المعرض",
  "Choose a photo": "اختر صورة",
  "Explained by the AI from the paper — check anything important with someone you trust.": "شرحه الذكاء الاصطناعي من المستند — تحقق من أي أمر مهم مع شخص تثق به.",
  "Read it all": "اقرأها بالكامل",
