  "Explain it simply": "اشرحها ببساطة",
  "Another paper": "مستند آخر",
  "Add to Family health": "إضافة إلى صحة العائلة",
  "I read the paper aloud, say what it is and what to do — and add its date or medicine where it belongs.": "أقرأ المستند بصوت مسموع، وأوضح ما هو وما يجب فعله — وأضيف تاريخه أو دواءه في مكانه المناسب.",
  "Read a paper to me": "اقرأ لي مستندًا",
