  "Tailor this CV to a job ad": "تخصيص هذه السيرة الذاتية لإعلان وظيفة",
  "I don't have a skills list for this job yet — the interview practice and job search still work.": "ليس لدي قائمة مهارات لهذه الوظيفة بعد — لا يزال التدريب على المقابلات والبحث عن وظائف يعملان.",
  "Interview practice": "التدريب على المقابلات",
