  "How did I do?": "كيف كان أدائي؟",
  "Ask the AI coach": "اسأل المدرب الذكي",
  "Find jobs": "البحث عن وظائف",
  "Apply with the PDF from this CV (the button at the top).": "قدّم باستخدام ملف PDF من هذه السيرة الذاتية (الزر في الأعلى).",
  "Voice input works in the Android app and in Chrome — or type your answer": "يعمل الإدخال الصوتي في تطبيق Android وفي Chrome — أو اكتب إجابتك",
  "Units left in your pens or vials (optional — for a refill reminder)": "الوحدات المتبقية في أقلامك أو قواريرك (اختياري — لتذكيرك بإعادة التعبئة)",
  "How many are left (optional — for a refill reminder)": "كم المتبقي منها (اختياري — لتذكيرك بإعادة التعبئة)",
