  "15 minutes since a low reading. Under 70 mg/dL: another 15 g of fast sugar.": "مرت 15 دقيقة منذ قراءة الانخفاض. إذا كان أقل من 70 مجم/ديسيلتر: تناول 15 جم أخرى من السكريات سريعة الامتصاص.",
  "How to use Attune": "طريقة استخدام Attune",
