  "Every tool in three steps, with a drawing of its screen. Tap a step to see where it happens, or play them all.": "كل أداة في ثلاث خطوات مع رسم لشاشتها. اضغط على أي خطوة لترى أين تحدث، أو شغّلها بالكامل.",
