  "{n} coming back later": "{n} ستعود لاحقًا",
  "{n} learned": "تم تعلم {n}",
  "What you missed comes back in later lessons — soon at first, then further apart — until you know it.": "ما فاتك يعود في الدروس اللاحقة — سريعًا في البداية، ثم على فترات متباعدة — حتى تتقنه تمامًا.",
  "Level {n}": "المستوى {n}",
