  "Small models, no Studio, lighter effects": "نماذج صغيرة، دون Studio، وتأثيرات أخف",
  "Models up to Core, fast Studio pictures": "نماذج حتى Core، وصور سريعة في Studio",
  "Models up to Sense and Blaze+, sharper Studio pictures": "نماذج حتى Sense وBlaze+، وصور أكثر وضوحًا في Studio",
  "Every phone model up to Zenith+, full Studio": "كل طرازات الهواتف حتى Zenith+، مع Studio كامل",
  "Everything, the biggest models and full Studio": "كل شيء، بما في ذلك أكبر النماذج وStudio بالكامل",
  "Hide what is too heavy": "إخفاء ما هو ثقيل جدًا",
  "Show every tool anyway": "عرض كل الأدوات على أي حال",
  "Ask your life": "اسأل عن حياتك",
  "One question about your money, people, health, meals and deadlines — answered from your own data": "سؤال واحد عن أموالك، أو معارفك، أو صحتك، أو وجباتك، أو مواعيدك النهائية — تجاب من واقع بياناتك الخاصة",
  "Ask about your money, health, people, meals or deadlines…": "اسأل عن أموالك، أو صحتك، أو معارفك، أو وجباتك، أو مواعيدك النهائية…",
  "Try": "جرّب",
  "Asked before": "سألت عنه من قبل",
  "Answered from your own records on this device, by code — nothing is sent anywhere, and every number can be checked in the tool it came from.": "تتم الإجابة من سجلاتك الخاصة على هذا الجهاز برمجيًا — لا يتم إرسال أي شيء لأي مكان، ويمكن التحقق من كل رقم في الأداة التي أتى منها.",
  "From": "المصدر",
  "Open {t}": "افتح {t}",
  "Nothing in your own data answers this. Chat can answer general questions.": "لا يوجد في بياناتك الخاصة ما يجيب عن هذا. يمكن للمحادثة الإجابة عن الأسئلة العامة.",
  "Ask Chat": "اسأل المحادثة",
  "One question, answered from everything Attune keeps for you — money, debts, medicines, lab results, meals, deadlines and notes.": "سؤال واحد، تجاب عنه من كل ما يحتفظ به Attune لك — الأموال والديون والأدوية ونتائج التحاليل والوجبات والمواعيد النهائية والملاحظات.",
