  "Scout checks each goal when you open Attune (at most twice a day), once at night on the phone, and whenever you tap Check now, and tells you only about strong new finds or price drops. It reads public ads only and never contacts anyone or pays for you.": "يفحص Scout كل هدف عند فتح Attune (مرتين يوميًا كحد أقصى)، ومرة ليلاً على الهاتف، وكلما ضغطت على افحص الآن، ويخبرك فقط بالاكتشافات الجديدة القوية أو انخفاض الأسعار. يقرأ الإعلانات العامة فقط ولا يتصل بأحد أو يدفع نيابة عنك.",
  "Nothing that matches yet. Scout keeps looking — you'll be told when something good appears.": "لا توجد نتائج مطابقة بعد. يواصل Scout البحث — وسيتم إبلاغك عند ظهور شيء جيد.",
