  "Flash mode on this phone: the model stays on storage and only the experts each word needs are read into memory — about 3–8 words a second, slower than the small models but far more knowledgeable. Needs {g} GB free storage.": "الوضع السريع على هذا الهاتف: يبقى النموذج في التخزين ويتم تحميل الخبراء الذين تتطلبهم كل كلمة فقط إلى الذاكرة — بمعدل 3 إلى 8 كلمات في الثانية تقريبًا، وهو أبطأ من النماذج الصغيرة ولكنه أكثر معرفة بمراحل. يتطلب {g} جيجابايت مساحة تخزين خالية.",
