  "Each lesson is a section of the book in its own words (with its source), so it works without a model; with a model loaded, it is explained more simply from that text only.": "كل درس هو قسم من الكتاب بكلماته الأصلية (مع مصدره)، لذا فهو يعمل دون الحاجة لنموذج ذكاء اصطناعي؛ وعند تحميل نموذج، يتم شرحه بصيغة أبسط اعتمادًا على ذلك النص فقط.",
  "That section isn't in the pack on this phone — is the pack still installed?": "هذا القسم غير موجود في الحزمة على هذا الهاتف — هل الحزمة لا تزال مثبتة؟",
