  "Running on the NPU ({d}).": "يعمل على وحدة المعالجة العصبية NPU ({d}).",
  "Runs the model on the Snapdragon NPU (Hexagon): much cooler, often faster at reading. Works best with Core Max (8-bit). Switches itself back to the CPU if anything goes wrong.": "يشغل النموذج على وحدة المعالجة العصبية Snapdragon NPU (Hexagon): حرارة أقل بكثير، وقراءة أسرع في كثير من الأحيان. يعمل بشكل مثالي مع Core Max (8-bit). يعود تلقائيًا إلى المعالج المركزي CPU إذا حدث أي خطأ.",
  "This phone's NPU could not be used by the engine — Attune stays on the CPU.": "تعذر استخدام NPU الخاص بهذا الهاتف بواسطة المحرك — يظل Attune يعمل على CPU.",
  "Last time, starting on the NPU closed the app. Attune is back on the CPU; you can try it again in Engine → Speed.": "في المرة السابقة، تسبب بدء التشغيل على NPU في إغلاق التطبيق. عاد Attune إلى CPU؛ يمكنك تجربته مجددًا من المحرّك ← السرعة.",
  "Item name": "اسم الصنف",
  "Core Max, Sense, Zenith, Apex and Everest run on a computer: get them in the Attune desktop app.": "تعمل Core Max وSense وZenith وApex وEverest على جهاز الحاسوب: احصل عليها من تطبيق Attune للحاسوب.",
  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "ثقيل جدًا على الهاتف — قد يتسبب في إغلاق التطبيق. يعمل Core أو Blaze بسلاسة هنا؛ وهذا النموذج متوفر في تطبيق الحاسوب.",
