  "Needed from now: {x} kg a week": "المطلوب من الآن: {x} كجم أسبوعيًا",
  "Needed from now: {x} a month": "المطلوب من الآن: {x} شهريًا",
  "Mission started — Attune works on it every day": "بدأت المهمة الكبرى — يعمل Attune عليها كل يوم",
  "Say a goal with a deadline. Attune works on it every day: it reads your money, food and Scout ads, gives your real chance, and the one step for today.": "حدد هدفًا بموعد نهائي. يعمل Attune عليه يوميًا: يقرأ أموالك وطعامك وإعلانات Scout، ويعطيك نسبتك الحقيقية، والخطوة الواحدة لليوم.",
  "e.g. «عايز أوفر 60 ألف قبل يونيو»": "مثال: «أريد توفير 60 ألفًا قبل يونيو»",
  "Save {t}": "توفير {t}",
  "Lose {t} kg": "خسارة {t} كجم",
  "Buy it for {t} or less": "شراؤه بمبلغ {t} أو أقل",
  "by {d}": "بحلول {d}",
  "add a date (e.g. by June)": "أضف تاريخًا (مثل: قبل يونيو)",
  "Say a number and a date: save 60,000 by June · lose 6 kg before 20 January · buy … under 900k by 1 December · spend no more than 3,000 on food this month · pay off Ahmed's debt by December · finish the Turkish course by December.": "حدد رقمًا وتاريخًا: توفير 60,000 بحلول يونيو · خسارة 6 كجم قبل 20 يناير · شراء … بأقل من 900 ألف بحلول 1 ديسمبر · عدم إنفاق أكثر من 3,000 على الطعام هذا الشهر · سداد دين أحمد بحلول ديسمبر · إنهاء دورة اللغة التركية بحلول ديسمبر.",
  "Start the mission": "بدء المهمة الكبرى",
  "Your money missions need {a} a month together, but you keep about {b}. Pause one, or move a date.": "تتطلب مهامك المالية معًا {a} شهريًا، ولكنك تدخر حوالي {b}. أوقف إحداها مؤقتًا، أو غيّر موعدًا.",
  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "لا توجد مهام كبرى بعد. ابدأ واحدة أعلاه — هدف ادخار، أو هدف وزن، أو شيئًا لشرائه، أو حد إنفاق، أو دينًا، أو دورة تدريبية.",
  "A goal with a date — Attune works on it every day": "هدف بموعد محدد — يعمل Attune عليه كل يوم",
  "{c}% chance": "فرصتك {c}%",
  "A goal with a date — Attune works on it every day and shows your real chance": "هدف بموعد محدد — يعمل Attune عليه كل يوم ويعرض فرصتك الحقيقية",
  "Where": "المكان",
  "Every tool in three steps, with a drawing of its screen — and a plan to make Attune part of your day.": "كل أداة في ثلاث خطوات مع رسم لشاشتها — وخطة لجعل Attune جزءًا من يومك.",
  "Sync": "مزامنة",
  "Backup & sync": "نسخة احتياطية ومزامنة",
  "Synced — {a} new, {c} updated. Reopening…": "تمت المزامنة — {a} جديد، {c} محدث. جارٍ إعادة الفتح…",
  "Waiting for the other device…": "في انتظار الجهاز الآخر…",
  "Merging…": "جارٍ الدمج…",
  "Locking and sending…": "جارٍ التشفير والإرسال…",
  "Signing in to Google…": "جارٍ تسجيل الدخول إلى Google…",
  "Locking and uploading…": "جارٍ التشفير والرفع…",
  "Type the address shown on the other device, like 192.168.1.20:41873": "اكتب العنوان الظاهر على الجهاز الآخر، مثل 192.168.1.20:41873",
  "The code has 8 letters and numbers": "يتكون الرمز من 8 أحرف وأرقام",
  "Set your sync passphrase first — the same on every device.": "عيّن عبارة مرور المزامنة أولاً — المتطابقة على كل جهاز.",
  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "اجعل هاتفك وحاسوبك (أو هاتفين) متطابقين دائمًا. يتم تشفير البيانات قبل مغادرتها هذا الجهاز؛ وما تحذفه في جهاز يُحذف في الآخر، دون فقدان أي شيء آخر.",
  "Wi-Fi": "Wi-Fi",
  "Google Drive": "Google Drive",
  "Allow Attune to find your other device on this Wi-Fi (Android asks once).": "اسمح لـ Attune بالعثور على جهازك الآخر على شبكة Wi-Fi هذه (يطلب Android الإذن مرة واحدة).",
  "On the other device: Backup → Sync → Wi-Fi → Connect, and type:": "على الجهاز الآخر: النسخ الاحتياطي ← المزامنة ← Wi-Fi ← الاتصال، واكتب:",
  "not on Wi-Fi": "غير متصل بشبكة Wi-Fi",
  "Show a code on this device": "عرض رمز على هذا الجهاز",
  "Or connect to the other device": "أو الاتصال بالجهاز الآخر",
  "Make this device exactly like the other one (removes what the other doesn't have)": "اجعل هذا الجهاز مطابقًا تمامًا للجهاز الآخر (يحذف ما ليس موجودًا في الآخر)",
  "Connect and sync": "اتصال ومزامنة",
  "One file in your own Google Drive, in a hidden folder only Attune can open. It is locked with your sync passphrase on this device, so Google only stores noise.": "ملف واحد في حساب Google Drive الخاص بك، في مجلد مخفي لا يمكن إلا لـ Attune فتحه. وهو مشفر بعبارة مرور المزامنة على هذا الجهاز، لذا لا تخزن Google سوى بيانات مشفرة غير مقروءة.",
  "Sync passphrase set on this device.": "تم تعيين عبارة مرور المزامنة على هذا الجهاز.",
  "Sync passphrase (10+ characters, the same on every device)": "عبارة مرور المزامنة (10 أحرف فأكثر، متطابقة على كل جهاز)",
  "Save passphrase": "حفظ عبارة المرور",
  "Sync with Google Drive": "مزامنة مع Google Drive",
  "Last synced: {d}": "آخر مزامنة: {d}",
  "Wrong code or passphrase — nothing was changed.": "رمز أو عبارة مرور خاطئة — لم يتغير أي شيء.",
  "Use at least 10 characters — the file lives in your Drive, so the passphrase is its only lock.": "استخدم 10 أحرف على الأقل — الملف موجود في Drive، لذا فإن عبارة المرور هي قفله الوحيد.",
  "That passphrase is too easy to guess.": "عبارة المرور هذه سهلة التخمين جدًا.",
  "Only available in the Attune app": "متاح فقط في تطبيق Attune",
  "Google sync on the computer comes in the next update — use Wi-Fi with your phone for now.": "مزامنة Google على الحاسوب قادمة في التحديث القادم — استخدم Wi-Fi مع هاتفك حاليًا.",
  "Remember your notes": "تذكّر ملاحظاتك",
  "{n} notes to look at again today · about a minute": "{n} ملاحظات للمراجعة مرة أخرى اليوم · تستغرق حوالي دقيقة",
  "{n} left": "متبقٍ {n}",
  "first time": "أول مرة",
  "Try to remember what it says, then show it.": "حاول تذكر ما تحتويه، ثم اعرضها.",
  "Forgot": "نسيت",
  "Hard": "صعب",
  "Done for today — they will come back when you are about to forget them.": "انتهيت لليوم — ستعود الملاحظات عندما توشك على نسيانها.",
  "Edit your brand kit": "تعديل الهوية البصرية لشركتك",
  "+ Your brand kit (logo, colour, name)": "+ الهوية البصرية لشركتك (الشعار، اللون، الاسم)",
