  "Add logo": "إضافة شعار",
  "Use my brand": "استخدام هويتي البصرية",
  "Your brand": "هويتك البصرية",
  "Add photos": "إضافة صور",
  "Each photo gets the time and the place": "تحصل كل صورة على الوقت والمكان",
  "What it shows (optional)": "ماذا توضح الصورة (اختياري)",
  "Report with {n} photos (PDF)": "تقرير مع {n} صور (PDF)",
  "Report as PDF": "تقرير كملف PDF",
  "Cut": "قص",
