  "Show this to your doctor — the trend says more than one result.": "اعرض هذا على طبيبك — فالمسار العام يعبر عن الحالة أكثر من نتيجة منفردة.",
  "Your watch's temperature rose {r} °C: ovulation around {o}, so the period is expected {n}.": "ارتفعت درجة حرارة ساعتك بمقدار {r} درجة مئوية: التبويض حول {o}، لذا يُتوقع بدء الدورة في {n}.",
  "(your own {d} days after ovulation)": "(بعد {d} أيام من التبويض حسب بياناتك الخاصة)",
  "(14 days after ovulation until 2 cycles are measured)": "(14 يومًا بعد التبويض حتى يتم قياس دورتين)",
  "No temperature rise yet — ovulation looks later than usual, so the period will likely be later than the date above.": "لا يوجد ارتفاع في درجة الحرارة بعد — يبدو أن التبويض متأخر عن المعتاد، لذا يُرجح أن تتأخر الدورة عن الموعد أعلاه.",
  "{n} nights of temperature from your watch — the rise after ovulation shows here.": "درجة الحرارة لـ {n} ليالٍ من ساعتك — يظهر الارتفاع بعد التبويض هنا.",
  "A watch that measures night temperature (Galaxy Watch, Pixel Watch, Oura…) makes the prediction more exact.": "الساعة التي تقيس درجة الحرارة ليلاً (Galaxy Watch، Pixel Watch، Oura…) تجعل التوقع أكثر دقة.",
