  "Subtitles need Android 13 or newer": "الترجمة المصاحبة تتطلب نظام Android 13 أو أحدث",
  "Google sync on the computer needs one setup step by Attune's owner (its Google client) — use Wi-Fi with your phone until then.": "تتطلب مزامنة Google على الحاسوب خطوة إعداد واحدة من مالك Attune (معرّف عميل Google) — استخدم مزامنة Wi-Fi مع هاتفك حتى ذلك الحين.",
  "The first time, Google's sign-in page opens in your browser; after that the computer stays signed in.": "في المرة الأولى، تُفتح صفحة تسجيل الدخول إلى Google في متصفحك؛ وبعد ذلك يظل الحاسوب مسجلاً للدخول.",
