  "That language isn't installed for offline voice — add it in the phone's Settings → Google → Speech → Offline languages": "تلك اللغة غير مثبتة للتعرف الصوتي دون إنترنت — أضفها من إعدادات الهاتف ← Google ← الصوت ← اللغات دون اتصال",
