  "Talk to Attune": "التحدث إلى Attune",
  "Your details — bookings and better answers": "بياناتك — لحجوزات أسرع وإجابات أفضل",
  "Private: everything here stays on this phone — Attune never uploads it, and its AI runs on the phone. Answers and agents use only your trip and daily-life details (never your passport, phone or email). A booking site gets your name, passport and phone only when you tap “Fill my details”.": "خصوصية كاملة: كل ما هنا يبقى على هذا الهاتف فقط — لا يرفعه Attune أبدًا، ويعمل ذكاؤه الاصطناعي محليًا. تستخدم الإجابات والوكلاء تفاصيل رحلاتك ويومياتك فقط (دون استخدام جواز السفر أو الهاتف أو البريد إطلاقًا). ولا يتلقى موقع الحجز اسمك وجوازك وهاتفك إلا عند ضغطك على «تعبئة بياناتي».",
  "Use my details to make answers and agents fit me": "استخدام بياناتي لتخصيص الإجابات والوكلاء لتناسبني",
  "Trips and hotels": "الرحلات والفنادق",
  "Agents use these when your sentence doesn't say — e.g. a hotel watch looks for your stars by itself.": "يستخدمها الوكلاء عندما لا توضح جملتك ذلك — مثل مراقبة الفنادق حسب عدد نجومك المفضل تلقائيًا.",
  "Daily life": "الحياة اليومية",
