  "The AI that answers, reads photos and writes — on your phone, private. {s}. Best on Wi-Fi.": "الذكاء الاصطناعي الذي يجيب ويقرأ الصور ويكتب — على هاتفك بخصوصية تامة. بحجم {s}. يُفضل التنزيل عبر Wi-Fi.",
