  "You are on Free: unlimited answers, Money and Follow-ups. Pro adds agents that act for you, photo meals, Deal Check, Chat X-Ray, reports and exports.": "أنت على الخطة المجانية: إجابات غير محدودة، وقسم المال، والمتابعات. تضيف باقة Pro وكلاء يعملون نيابة عنك، وقراءة الوجبات بالصور، وفحص الصفقات، والأشعة السينية للمحادثات، والتقارير والتصدير.",
  "Agents that find, watch and buy for you (you confirm every order)": "وكلاء يبحثون ويراقبون ويشترون لأجلك (تؤكد أنت كل طلب بنفسك)",
