  "Try Attune — a private AI on your phone for your money, meals and reminders. With my link you get a month of Pro free: {l}": "جرّب Attune — ذكاء اصطناعي محلي خاص على هاتفك لإدارة أموالك ووجباتك وتذكيراتك. عبر رابِطي ستحصل على شهر مجاني في Pro: {l}",
