  "One shopping list, who paid what for the house, and reminders for your parents — shared with your family's phones only, locked with a family code. No account, no server.": "قائمة تسوق واحدة، وما تم إنفاقه على المنزل، وتذكيرات لوالديك — مشتركة مع هواتف عائلتك فقط، ومحمية برمز عائلي. دون حسابات أو خوادم وسيطة.",
