  "Everything about {n}": "كل ما يتعلق بـ {n}",
  "Nothing linked yet. When you write {n} (or another name of theirs) in Money, a note or a message, it shows here.": "لا توجد عناصر مرتبطة بعد. عند كتابة {n} (أو أي اسم بديل له) في قسم المال أو في ملاحظة أو رسالة، ستظهر هنا.",
  "The people, places and things in your life. Attune links everything about each one — payments, notes, messages, follow-ups — and Chat answers from it. Two with the same name? It asks which one.": "الأشخاص والأماكن والأشياء في حياتك. يربط Attune كل ما يتعلق بكل منها — مدفوعات، ملاحظات، رسائل، متابعات — وتجيب المحادثة منها. هل يوجد اثنان بالاسم نفسه؟ سيسألك أيهما تقصد.",
