  "Ask me about your own money, e.g. “how much did I spend on food this week?” or “what did I earn this month?”": "اسألني عن أموالك الخاصة، مثل: «كم أنفقت على الطعام هذا الأسبوع؟» أو «ما هو دخلي هذا الشهر؟»",
