  "Name, country, how Attune talks to you": "الاسم، والبلد، وطريقة مخاطبة Attune لك",
  "Payment pending — Pro turns on by itself as soon as Google confirms it.": "عملية الدفع معلقة — تتفعل باقة Pro تلقائيًا بمجرد تأكيد Google لها.",
  "Google Play: {e}": "Google Play: {e}",
  "SHA-256": "SHA-256",
  "owner/repo:QUANT": "owner/repo:QUANT",
  "With more than one model installed: quick questions use the one already running; code, maths, reasoning and long reports move to your strongest model that runs smoothly here, and photos to one that sees. A switch takes 10–30 s.": "عند تثبيت أكثر من نموذج: الأسئلة السريعة تستخدم النموذج المشغل بالفعل؛ والأكواد والرياضيات والتحليل المنطقي والتقارير الطويلة تنتقل إلى النموذج الأقوى الذي يعمل بسلاسة هنا، والصور إلى نموذج يدعم الرؤية. يستغرق التبديل 10–30 ثانية.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \\\"nothing leaves this phone\\\".": "النموذج نفسه لا يتصل بالشبكة مطلقًا. يسجل السجل كل اتصال أجراه التطبيق أو رفضه، موضحًا المضيف والسبب فقط — وهو الدليل الفعلي خلف شعار «لا يغادر أي شيء هذا الهاتف».",
  "When my salary arrives, put 20% in Savings": "عند وصول راتبي، ضع 20% في المدخرات",
  "When my salary arrives, put 10% in the Emergency fund": "عند وصول راتبي، ضع 10% في صندوق الطوارئ",
  "When a bonus arrives, put 50% in Savings": "عند ورود مكافأة، ضع 50% في المدخرات",
  "When InstaPay comes in, put 5% in the Car fund and tell me": "عند استلام تحويل عبر InstaPay، ضع 5% في صندوق السيارة وأخبرني",
  "Gas": "الغاز",
  "Mobile": "الهاتف المحمول",
  "I don't know your bills yet — after 3 months of electricity, water or internet in Money I'll tell you when each comes and how much.": "لا أعرف نمط فواتيرك بعد — بعد تسجيل 3 أشهر من الكهرباء أو المياه أو الإنترنت في قسم المال سأخبرك بموعد ورود كل منها وقيمتها التقديرية.",
