  "Customers who owe you more than 30 days get a polite WhatsApp statement from Money → Remind.": "العملاء المتأخرون أكثر من 30 يومًا يحصلون على كشف حساب مهذب عبر WhatsApp من: المال ← تذكير.",
  "Top customers & items (this month)": "أهم العملاء والأصناف (هذا الشهر)",
