  "Export to Excel (CSV)": "تصدير إلى Excel (CSV)",
  "This system has no stock, balances, due dates or bookings yet. Ask the AI to add them, e.g. \\\"add a Payments table linked to Invoices\\\".": "هذا النظام لا يحتوي على مخزون أو أرصدة أو تواريخ استحقاق أو حجوزات بعد. اطلب من الذكاء الاصطناعي إضافتها، مثل: \"أضف جدول مدفوعات مرتبطًا بالفواتير\".",
