  "Every time the books are opened with a PIN and something changed, an encrypted copy is kept on this phone (last 7 + one per month). It opens only with the PIN used that day.": "في كل مرة تُفتح فيها الدفاتر برمز PIN ويتم إجراء تعديل، تُحفظ نسخة مشفرة على هذا الهاتف (آخر 7 نسخ + نسخة واحدة شهريًا). ولا تُفتح إلا برمز PIN المستخدم في ذلك اليوم.",
