  "Open Settings (the building icon) and add your company name, tax number and logo — they print on every invoice.": "افتح الإعدادات (أيقونة المبنى) وأضف اسم شركتك ورقمها الضريبي وشعارها — لتُطبع على كل فاتورة.",
