  "Asks for a 4–6 digit PIN when the books are opened. It keeps casual eyes out on a shared phone; it is not encryption.": "يطلب رمز PIN مكونًا من 4 إلى 6 أرقام عند فتح الدفاتر. لمنع الفضوليين على الهاتف المشترك؛ وليس تشفيرًا للملفات.",
