  "Your books live only on this phone. Save a backup file regularly (to Drive, WhatsApp or a computer).": "دفاترك محفوظة على هذا الهاتف فقط. احفظ ملف نسخة احتياطية بانتظام (على Drive، أو WhatsApp أو الحاسوب).",
  "Danger zone": "منطقة العمليات الحساسة",
  "Erase ALL your books on this phone? Save a backup first — this cannot be undone.": "مسح جميع الدفاتر على هذا الهاتف نهائيًا؟ احفظ نسخة احتياطية أولاً — لا يمكن التراجع عن هذا الإجراء.",
