  "Which exact model and year is it most likely? Say which clues you used and how sure you are.": "ما هو الطراز وسنة الصنع الأرجح بدقة؟ اذكر القرائن المعتمدة ومدى تأكدك.",
  "Give its main specifications in a table.": "قدم أهم مواصفاته الفنية في جدول منظم.",
  "For my use, which one should I choose and why?": "بالنسبة لاستخدامي، أيهما ينبغي علي اختياره ولماذا؟",
  "What is the typical price difference between them?": "ما هو فارق السعر المعتاد بينهما في السوق؟",
  "What are the common mistakes and risks in these steps?": "ما هي الأخطاء الشائعة والمخاطر في هذه الخطوات؟",
  "Turn these steps into a short checklist I can tick.": "حوّل هذه الخطوات إلى قائمة مراجعة موجزة يمكنني التأشير عليها.",
  "Give me a real-world example with numbers.": "قدم لي مثالاً واقعيًا بالأرقام والحسابات.",
  "Explain that simply, as if I have no background.": "اشرح ذلك ببساطة شديدة، كما لو لم تكن لدي خلفية سابقة.",
  "Make it more formal.": "اجعلها أكثر رسمية.",
  "Make it shorter.": "اجعلها أقصر.",
  "Tell me more about the first option.": "أخبرني بالمزيد عن الخيار الأول.",
  "Turn the plan into a checklist.": "حوّل الخطة إلى قائمة مراجعة.",
  "Translate it back so I can check the meaning.": "ترجمها مجددًا إلى الأصل للتحقق من المعنى.",
  "Make that shorter — just the key points.": "اجعل ذلك أكثر إيجازًا — النقاط الجوهرية فقط.",
  "Go into more detail.": "اشرح بتفصيل أكثر.",
  "Double-check the calculations step by step.": "راجع الحسابات بدقة خطوة بخطوة.",
  "\n\n(Write the whole answer in English.)": "\n\n(اكتب الإجابة كاملةً باللغة العربية الفصحى.)",
