  "Give it to an agent (find, watch, order)": "إسنادها إلى وكيل (بحث، مراقبة، شراء)",
  "Save it as a note": "حفظ كملاحظة",
  "the start and end dates": "تاريخ البدء والانتهاء",
  "the rent and when it is paid": "قيمة الإيجار وموعد سداده",
  "the deposit and when it comes back": "مبلغ التأمين وموعد استرداده",
  "who pays for repairs": "الطرف المتحمل لتكاليف الصيانة والإصلاحات",
  "who pays electricity, water and gas": "الطرف المتحمل لفواتير الكهرباء والمياه والغاز",
