  "Can I see it and pay on delivery (cash / card on receipt)?": "هل يمكنني معاينة المنتج والدفع عند الاستلام (نقدًا أو بالبطاقة)؟",
  "What is the exact brand and model number? Can you send a photo of the label?": "ما هي الماركة ورقم الطراز الدقيق؟ هل يمكنك إرسال صورة لملصق البيانات؟",
  "Is there an official warranty, and for how long? Invoice included?": "هل يتوفر ضمان محلي معتمد وما هي مدته؟ وهل الفاتورة الضريبية مشمولة؟",
