  "“Tell me when hotels near the Haram are under 45k for 4 nights from 10 December”": "«أخبرني عندما تكون الفنادق القريبة من الحرم بأقل من 45 ألفًا لـ 4 ليالٍ من 10 ديسمبر»",
  "An agent checks the price twice a day and tells you when it drops — it also tracks deliveries, keeps your usual order and opens any app": "وكيل يفحص السعر مرتين يوميًا ويخبرك فور انخفاضه — ويتتبع الشحنات، ويحفظ وجبتك المعتادة، ويفتح أي تطبيق",
