  "Real ads from many sites, checked and compared — told when a good one appears": "إعلانات حقيقية من مواقع متعددة، مفحوصة ومقارنة — مع إشعارك فور ظهور عرض ممتاز",
  "Save a book, an article or a podcast": "حفظ كتاب أو مقال أو بودكاست",
