  "Tell me about yourself.": "حدثني عن نفسك.",
  "Why do you want this job?": "لماذا ترغب في الحصول على هذه الوظيفة؟",
  "Tell me about a problem you solved at work.": "حدثني عن مشكلة نجحت في حلها أثناء عملك.",
  "What is your biggest strength — with an example?": "ما هي نقطة قوتك الكبرى — مع ذكر مثال واقعي؟",
  "Tell me about a time you made a mistake. What did you do?": "حدثني عن موقف ارتكبت فيه خطأً ما. وكيف تصرفت حياله؟",
  "Where do you see yourself in three years?": "أين ترى نفسك بعد ثلاث سنوات من الآن؟",
  "Do you have any questions for us?": "هل لديك أي أسئلة تود طرحها علينا؟",
  "Walk me through a project you built. What was hardest?": "اشرح لي مراحل بناء مشروع طورته من قبل. وما الذي كان الأصعب فيه؟",
  "How do you make sure your code works?": "كيف تتأكد من سلامة الكود البرمجي وعمله بالشكل الصحيح؟",
  "Tell me about an analysis that changed a decision.": "حدثني عن تحليل بياني قمت به وغيّر مسار قرار إداري.",
  "How do you check that data is correct?": "كيف تتحقق من دقة وصحة البيانات والمعلومات؟",
  "How do you close the month?": "كيف تجري عمليات الإقفال المالي الشهري؟",
  "Tell me about a reconciliation that didn't match.": "حدثني عن عملية مطابقة وتسوية لم تكن متطابقة وكيف عثرت على الفارق.",
  "Tell me about your best month. What did you do differently?": "حدثني عن أفضل شهر حققت فيه أداءً استثنائيًا. وما الذي فعلته بشكل مختلف؟",
  "How do you handle a client who says it's too expensive?": "كيف تتعامل مع عميل يرى أن السعر المعروض مرتفع للغاية؟",
  "Tell me about a campaign and its results.": "حدثني عن حملة تسويقية أدرتها وما النتائج التي حققتها.",
  "How do you decide where to spend the budget?": "كيف تتخذ قرار توزيع الميزانية وأوجه الإنفاق؟",
  "Tell me about an angry customer you helped.": "حدثني عن عميل غاضب ساعدته في حل مشكلته بنجاح.",
  "What do you do when you don't know the answer?": "ماذا تفعل عندما تواجه سؤالاً أو مشكلة لا تعرف إجابتها؟",
  "Tell me about a time a patient's condition changed quickly.": "حدثني عن حالة مريض تغيرت حالته الصحية بشكل مفاجئ وسريع وكيف تصرفت.",
  "How do you help a student who is falling behind?": "كيف تساعد طالبًا يتعثر ويتراجع مستواه الدراسي؟",
  "Tell me about a project that was late. What did you do?": "حدثني عن مشروع تأخر عن موعد تسليمه المحدد. ماذا فعلت لتداركه؟",
  "Walk me through a design from brief to final.": "اشرح لي خطوات إعداد التصميم بدءًا من ملخص الفكرة وحتى النسخة النهائية.",
  "How do you find good candidates for a hard role?": "كيف تستقطب وتختار المرشحين الأكفاء لوظيفة تتطلب مهارات نادرة وصعبة؟",
  "Tell me about a site problem you solved.": "حدثني عن مشكلة ميدانية في موقع العمل نجحت في حلها.",
  "What do you do if a delivery can't be completed?": "ماذا تفعل إذا تعذر إتمام عملية التوصيل أو التسليم لأي سبب؟",
  "How do you plan a lift near the chart's limit?": "كيف تخطط لعملية رفع ثقيلة تقترب من الحد الأقصى المسموح في جدول الأحمال؟",
  "How do you keep quality during a rush?": "كيف تحافظ على معايير الجودة العالية أثناء فترات ضغط العمل والتسرع؟",
  "How do you handle many urgent tasks at once?": "كيف تدير وتوفق بين مهام عاجلة متعددة في وقت واحد؟",
  "A clear story: what happened → what you did → the result.": "قصة واضحة ومحددة: ما الذي حدث ← ما الذي فعلته أنت ← ما هي النتيجة.",
  " is missing.": " ناقصة وغير مكتملة.",
  "A number makes the result believable.": "ذكر الأرقام والإحصائيات يجعل النتيجة واقعية ومقنعة.",
  "Add a number to the result (how many, how much, how fast).": "أضف رقمًا أو نسبة للنتيجة (كم عدد، كم قيمة، كم وفرت من الوقت).",
  "It matches what your CV says.": "مطابق وموثق لما هو مسجل في سيرتك الذاتية.",
  "Tell every answer as a story: what happened, what YOU did, and the result with a number.": "اروِ كل إجابة في صورة قصة متكاملة: ما حدث، وما قمت به أنت شخصيًا، والنتيجة مدعمة برقم أو نسبة.",
  "Replace “um” and “like” with a short pause — a second of silence sounds more confident.": "استبدل كلمات التردد والحشو بصمت قصير وتوقف هادئ — فثانية من الصمت توحي بثقة أكبر في النفس.",
  "Say “I did” and “it worked” instead of “I think” and “maybe”.": "قل «قمت بكذا» و«نجح الأمر» بدلاً من عبارات الشك مثل «أعتقد» و«ربما».",
  "Keep a steady pace: 110–170 words a minute.": "حافظ على إيقاع ونبرة حديث ثابتة ومتزنة: بمعدل 110–170 كلمة في الدقيقة.",
