  "a sheep or goat": "شاة (من الضأن أو الماعز)",
  "a she-camel in her 2nd year (bint makhāḍ)": "بنت مخاض (ناقة أتمت سنتها الأولى ودخلت في الثانية)",
  "a she-camel in her 3rd year (bint labūn)": "بنت لبون (ناقة أتمت سنتين ودخلت في الثالثة)",
  "a she-camel in her 4th year (ḥiqqah)": "حقة (ناقة أتمت ثلاث سنين ودخلت في الرابعة)",
  "a she-camel in her 5th year (jadhaʿah)": "جذعة (ناقة أتمت أربع سنين ودخلت في الخامسة)",
  "a one-year-old calf (tabīʿ)": "تبيع (عجل أتم سنة كاملة ودخل في الثانية)",
