  "Saved items": "المحفوظات",
  "Close this Zakāt year? Its payments become one closed year with a certificate, and a new Zakāt year starts today.": "هل تريد إغلاق سنة الزكاة هذه؟ ستصبح مدفوعاتها سنة مغلقة لها شهادة، وتبدأ سنة زكاة جديدة اليوم.",
  "Closed — the certificate is under Closed years": "أُغلقت — الشهادة تحت «السنوات المغلقة»",
  "Ramadan is here — Zakāt al-Fiṭr is due before the Eid prayer": "حلّ رمضان — زكاة الفطر واجبة قبل صلاة العيد",
  "One question before your Zakāt is worked out": "سؤال واحد قبل حساب زكاتك",
  "You owe {a}. Scholars differ on whether a debt is taken off the wealth you pay Zakāt on. It is your choice — until you choose, nothing is taken off.": "عليك {a}. اختلف العلماء في خصم الدين من المال الذي تُزكّيه. الاختيار لك — وإلى أن تختار لا يُخصم شيء.",
  "Below the niṣāb": "أقل من النصاب",
