  "Zakāt {a} · 2.5% of {b}": "الزكاة {a} · ٢٫٥٪ من {b}",
  "Niṣāb {a}": "النصاب {a}",
  "{n} g of {m} g": "{n} غ من {m} غ",
  "Livestock Zakāt": "زكاة الأنعام",
  "{n} head": "{n} رأس",
  "Not free-grazing — no Zakāt on them": "ليست سائمة — لا زكاة فيها",
  "Below the niṣāb ({n} head)": "أقل من النصاب ({n} رأس)",
  "Due now: {x}": "مستحقة الآن: {x}",
  "Its ḥawl is running — due {d} (in {n} days)": "الحول جارٍ — مستحقة {d} (بعد {n} يومًا)",
  "Paid vs due": "المدفوع والمستحق",
  "Paid so far": "المدفوع حتى الآن",
  "Still to pay": "المتبقي",
  "Fully paid — may Allah accept it": "دُفعت كاملة — تقبّل الله",
  "Close this Zakāt year": "أغلق سنة الزكاة هذه",
  "Closed years": "السنوات المغلقة",
  "No closed year yet — when you finish paying a year's Zakāt, close it here and keep its certificate.": "لا توجد سنة مغلقة بعد — عندما تنتهي من دفع زكاة سنة، أغلقها هنا واحتفظ بشهادتها.",
  "An estimate to guide you. It uses the gold nisab (85g) and 2.5% on cash, gold, silver and money owed to you — not your home, car, or work equipment. Rulings on debts and on dropping below nisab during the year differ between scholars; confirm your case with a trusted scholar.": "تقدير للاسترشاد. يعتمد على نصاب الذهب (٨٥ غ) ونسبة ٢٫٥٪ على النقد والذهب والفضة والديون المستحقة لك — لا على منزلك أو سيارتك أو معدات عملك. تختلف أحكام الديون ونقص المال عن النصاب أثناء الحول بين العلماء؛ تأكد من حالتك مع عالم موثوق.",
  "Nothing yet today — tell the box what you spent or need to remember.": "لا شيء اليوم بعد — أخبر المربع بما أنفقته أو بما تريد تذكّره.",
  "These offers were read before Attune could read the hotel names and photos — tap Check now to get them.": "قُرئت هذه العروض قبل أن يتمكن Attune من قراءة أسماء الفنادق وصورها — اضغط «افحص الآن» للحصول عليها.",
