  "Have a nice trip! Make a travel list once — “make my travel checklist: passport, charger…” — and it comes back before every trip.": "رحلة سعيدة! أنشئ قائمة سفر مرة واحدة — «أنشئ قائمة سفر: جواز السفر، الشاحن…» — وستعود قبل كل رحلة.",
