  "Birthdays, reminders to people, a message for later — once, or every day, week, month or year.": "أعياد الميلاد، تذكيرات للناس، رسالة لاحقًا — مرة واحدة، أو كل يوم أو أسبوع أو شهر أو سنة.",
  "asks first": "يسأل أولًا",
