  "Through the chat's own reply when its notification is on your phone; otherwise a notification opens the chat with the message written — one tap on Send.": "عبر رد المحادثة نفسه عندما يكون إشعارها على هاتفك؛ وإلا يفتح إشعارٌ المحادثة والرسالة مكتوبة — ضغطة واحدة على إرسال.",
