  "What “Send by itself” does": "ماذا يفعل «أرسل تلقائيًا»",
  "At a message's time, Attune opens that WhatsApp chat with your message written and presses Send for you.": "في موعد الرسالة، يفتح Attune محادثة واتساب تلك ورسالتك مكتوبة ويضغط إرسال عنك.",
  "It uses Android's Accessibility service only for that: only in WhatsApp, only for messages you scheduled, only when the box holds your message.": "يستخدم خدمة إمكانية الوصول في أندرويد لذلك فقط: في واتساب فقط، وللرسائل التي جدولتها فقط، وعندما يحمل الحقل رسالتك فقط.",
  "It reads nothing else and sends nothing else. When the phone is locked it can't — you get the one-tap notification instead.": "لا يقرأ ولا يرسل أي شيء آخر. وعندما يكون الهاتف مقفلًا لا يستطيع — يصلك إشعار الضغطة الواحدة بدلًا من ذلك.",
  "Open Accessibility settings": "افتح إعدادات إمكانية الوصول",
  "In Settings: Accessibility → Attune → turn it on. Come back here after.": "في الإعدادات: إمكانية الوصول ← Attune ← فعّله. ثم عد إلى هنا.",
  "Attune answers by itself through the chat's own reply — it needs Notification access, and works in every version.": "يرد Attune تلقائيًا عبر رد المحادثة نفسه — يحتاج إلى الوصول إلى الإشعارات، ويعمل في كل الإصدارات.",
