  "Your limits": "حدودك",
  "e.g. car licence expires 3 Feb 2027, plate أ ب ج 1234": "مثال: رخصة السيارة تنتهي ٣ فبراير ٢٠٢٧، لوحة أ ب ج ١٢٣٤",
