  "Operator licence": "رخصة المشغّل",
  "Follow-ups → ⋯ → Errands. Type it once: “car licence expires 3 Feb 2027, plate أ ب ج 1234”.": "المتابعات ← ⋯ ← المهام. اكتبها مرة: «رخصة السيارة تنتهي ٣ فبراير ٢٠٢٧، لوحة أ ب ج ١٢٣٤».",
  "Before it is due it shows under Needs you, with the papers to bring.": "قبل موعدها تظهر تحت «يحتاجك» مع الأوراق المطلوبة.",
  "Open the official page — Attune reads what is due; you press Pay.": "افتح الصفحة الرسمية — يقرأ Attune المستحق؛ وأنت من يدفع.",
  "Traffic fines, bills, licences, a crane's inspection — all in one list.": "المخالفات والفواتير والرخص وفحص الرافعة — كلها في قائمة واحدة.",
  "driving licence expires 20 Nov 2026": "رخصة القيادة تنتهي ٢٠ نوفمبر ٢٠٢٦",
  "Driving licence · in 13 days": "رخصة القيادة · بعد ١٣ يومًا",
  "“Car licence expires 3 Feb 2027”": "«رخصة السيارة تنتهي ٣ فبراير ٢٠٢٧»",
  "Told before it is due, with the papers to bring": "تنبيه قبل الموعد، مع الأوراق المطلوبة",
  "Each place is one page with tabs on top — Money opens on your money, with Follow-ups next to it.": "كل مكان صفحة واحدة وفوقها تبويبات — «المال» تفتح على أموالك، وبجانبها «المتابعات».",
  "Attune puts it in the right place — Money, Reminders, People & plans, To-dos, Dates — and says what it did. Wrong? Tap Undo.": "يضعها Attune في مكانها الصحيح — المال، التذكيرات، الأشخاص والالتزامات، المهام، المواعيد — ويخبرك بما فعل. خطأ؟ اضغط «تراجع».",
  "One sentence does a lot: “Ahmed owes me 12,000, 1,000 a month” becomes 12 payments with a reminder before each one.": "جملة واحدة تفعل الكثير: «أحمد مدين لي بـ12,000، 1,000 شهريًا» تصبح 12 دفعة مع تذكير قبل كل منها.",
  "Type a goal with a number and a date: «عايز أوفر 60 ألف قبل يونيو», “lose 6 kg before 20 January”, a Corolla 2022 under 900,000 before 1 December. Tap Start the mission. More kinds: a spending limit («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده») and a debt from Money → People («عايز أخلص دين أحمد قبل ديسمبر»).": "اكتب هدفًا فيه رقم وتاريخ: «أريد أن أدّخر 60 ألفًا قبل يونيو»، «أنقص 6 كيلو قبل 20 يناير»، كورولا 2022 بأقل من 900,000 قبل 1 ديسمبر. اضغط «ابدأ المهمة». أنواع أخرى: حد للمصروف («لا أريد أن أنفق أكثر من 3000 على الطعام هذا الشهر») ودين من المال ← الأشخاص («أريد سداد دين أحمد قبل ديسمبر»).",
  "Every time Attune opens it reads your Money and the prices your agents saw, and shows your real chance (from your own past days, thousands of possible futures) and your progress.": "كل مرة يُفتح فيها Attune يقرأ أموالك والأسعار التي رآها الوكلاء، ويريك فرصتك الحقيقية (من أيامك السابقة وآلاف المستقبلات الممكنة) وتقدّمك.",
  "Tools holds Writing, Files & Converter and Ask a PDF — tap one to open it.": "الأدوات فيها الكتابة، والملفات والتحويل، واسأل PDF — اضغط واحدة لتفتحها.",
  "Paste once, then try another action on the same text.": "الصق مرة واحدة، ثم جرّب إجراءً آخر على النص نفسه.",
  "Save it as:": "احفظها كـ:",
  "Or say how — “remind me Monday at 9”, “subscription 200 every month”": "أو قل كيف — «ذكّرني يوم الاثنين الساعة 9»، «اشتراك 200 كل شهر»",
  "I couldn't read that — try “reminder tomorrow at 9” or “expense 450”": "لم أفهم ذلك — جرّب «ذكّرني غدًا الساعة 9» أو «مصروف 450»",
  "If your money stays as it is, you will pay about {a} on {d} ({p}% of {b}).": "إن بقيت أموالك كما هي، فستدفع نحو {a} يوم {d} ({p}% من {b}).",
  "If your money stays as it is, it stays under the niṣāb — no Zakāt this year.": "إن بقيت أموالك كما هي، فستبقى دون النصاب — لا زكاة هذا العام.",
