  "I couldn't read that — try: “the maid is now taking 700” or “remind me Sunday at 5 to call the client”": "لم أفهم — جرّب: «الخادمة أصبحت بـ٧٠٠» أو «ذكّرني الأحد الساعة ٥ بالاتصال بالعميل»",
