  "Which one do you mean? {list}": "من تقصد؟ {list}",
  "{w} is a plan with a total of {t} — change it in People & plans so the total stays right.": "{w} خطة بإجمالي {t} — غيّرها من «الأشخاص والالتزامات» ليبقى الإجمالي صحيحًا.",
