  "I didn't get that — try “Nada is my wife”, “tell me when my wife gets home” or “never show Yazio”.": "لم أفهم — جرّب «ندى زوجتي» أو «أخبرني عندما تصل زوجتي إلى البيت» أو «لا تعرض يازيو».",
