  "Pick from contacts": "اختر من جهات الاتصال",
  "Attune sees only the contact you pick — it never reads your contacts.": "يرى أتيون جهة الاتصال التي تختارها فقط — ولا يقرأ جهات اتصالك أبدًا.",
  "Reading the text…": "أقرأ النص…",
  "Checking it with the photo model…": "أتحقق بنموذج الصور…",
  "I couldn't read classes in this photo. Try a sharper photo or a screenshot of the timetable.": "لم أستطع قراءة محاضرات في هذه الصورة. جرّب صورة أوضح أو لقطة شاشة للجدول.",
  "I couldn't read classes in this photo. An Arabic or handwritten timetable needs a model marked 📷 in Engine.": "لم أستطع قراءة محاضرات في هذه الصورة. الجدول العربي أو المكتوب بخط اليد يحتاج نموذجًا عليه 📷 في المحرك.",
  "{n} classes saved — a reminder {m} min before each": "حُفظت {n} محاضرة — تذكير قبل كل واحدة بـ{m} دقيقة",
  "Timetable → reminders": "الجدول ← تذكيرات",
  "A photo or screenshot of your timetable. Attune reads it, you check it once, and every class gets a weekly reminder until the term ends.": "صورة أو لقطة شاشة لجدولك. يقرؤه أتيون، تراجعه مرة واحدة، ولكل محاضرة تذكير أسبوعي حتى نهاية الفصل.",
  "Use another photo": "استخدم صورة أخرى",
  "Choose the timetable photo": "اختر صورة الجدول",
  "Check every class — fix anything wrong": "راجع كل محاضرة — صحّح أي خطأ",
  "Check this one — only one reader saw it": "راجع هذه — قارئ واحد فقط رآها",
